function main({attachmentStr, imageStr, baozhangDanStr}){
    let fileList = [];

    try {
        // 解析并合并原始附件列表和电子影像列表
        if (attachmentStr && attachmentStr.trim()) {
            const attachmentList = JSON.parse(attachmentStr);
            if (Array.isArray(attachmentList)) {
                fileList.push(...attachmentList.filter(item => item));
            }
        }

        if (imageStr && imageStr.trim()) {
            const imageList = JSON.parse(imageStr);
            if (Array.isArray(imageList)) {
                fileList.push(...imageList.filter(item => item));
            }
        }

        // 解析报账单JSON
        const baozhangData = JSON.parse(baozhangDanStr);

        // 递归函数：查找包含filename和url字段的对象，排除"发票列表"对象
        function findFileObjects(obj) {
            const result = [];

            function traverse(current, parentKey = null) {
                if (current === null || typeof current !== 'object') {
                    return;
                }

                // 检查父级键名是否为"发票列表"，如果是则跳过整个分支
                if (parentKey === '发票列表') {
                    return;
                }

                if (parentKey === '其他信息-预付款核销') {
                    return;
                }

                // 检查当前对象是否同时包含filename和url字段
                if (typeof current === 'object' && 
                    !Array.isArray(current) && 
                    current.hasOwnProperty('filename') && 
                    (current.hasOwnProperty('url') || current.hasOwnProperty('url_origin'))) {
                    result.push({...current}); // 复制对象以避免引用问题
                }

                // 递归遍历对象的所有值
                if (Array.isArray(current)) {
                    current.forEach(item => traverse(item, parentKey));
                } else {
                    // 遍历对象时传递键名作为父级键名
                    Object.entries(current).forEach(([key, value]) => {
                        traverse(value, key);
                    });
                }
            }

            traverse(obj);
            return result;
        }

        // 从报账单数据中提取文件对象
        const extractedFiles = findFileObjects(baozhangData);
        fileList.push(...extractedFiles);

        // 去重处理（基于filename和url-origin的"?"之前的内容作为组合判定）
        const uniqueFileList = [];
        const seen = new Set();

        fileList.forEach(item => {
            const filename = item.filename || '';
            const urlOrigin = item['url-origin'] || item.url_origin || '';
            // 提取url-origin中"?"之前的内容
            const baseUrl = urlOrigin.split('?')[0];
            const key = `${filename}_${baseUrl}`;

            if (!seen.has(key)) {
                seen.add(key);
                uniqueFileList.push(item);
            }
        });

        return {
            file_list: uniqueFileList
        };
    } catch (error) {
        console.error("解析失败:", error.message);
        // 出错时返回原始数据合并
        return {
            file_list: [...(attachmentStr ? JSON.parse(attachmentStr || '[]') : []), 
                       ...(imageStr ? JSON.parse(imageStr || '[]') : [])]
        };
    }  
}

