    // 提取所需字段
    let accountName = data["报账信息-员工/供应商-户名"] || data["报账信息-供应商名称-户名"] || data["报账信息-员工/供应商名称-户名"] || data["报账信息-开户名"];
    let account = data["报账信息-员工/供应商-银行账号"] || data["报账信息-供应商名称-银行账号"] || data["报账信息-员工/供应商名称-银行账号"] || data["报账信息-银行账号"];
    const contractName = data["报账信息-合同名称"];
    const checkNum = JSON.parse(data2)["稽核行号"];

