                // 提取第二组信息（供应商开户名称）
                const secondPart = parts[1];
                const secondPartParts = secondPart.split(':');
                if (secondPartParts.length >= 2) {
                    accountName = secondPartParts[1];
                }
            }
        }
    }

    // 当account为空时，从补充信息中提取
    if (!account) {
        const supplementInfo = data["报账信息-员工/供应商 信息补充"];
        if (supplementInfo) {
            const parts = supplementInfo.split(' ');
            if (parts.length >= 3) {
                // 提取第三组信息（供应商银行账号）
                const thirdPart = parts[2];
                const thirdPartParts = thirdPart.split(':');
                if (thirdPartParts.length >= 2) {
                    account = thirdPartParts[1];
                }
            }
        }
    }

    // 清洗accountName：去掉空格、括号及其他特殊符号，只保留中文、英文、数字
    const cleanedAccountName = accountName ? accountName.replace(/[\s\(\)\[\]{}<>《》""''\-_+=%#@!~`\$\^&\*\|\\\/:;?,.【】（）]+/g, '') : '';

    // 清洗供应商账号：去掉半角和全角减号以及其他特殊字符
    const cleanedAccount = account 
      ? account.replace(/[\-\u2013\u2014\u2015\u2212]/g, '')  // 移除各种减号：- – — ― −
          .replace(/[\s$$$$$${}<>《》""''_+=%#@!~`\$\^&\*\|\\\/:;?,.【】（）]+/g, '') // 移除其他特殊字符字符
          .trim()
      : '';

    // 返回结果对象
    return {
        account_name: cleanedAccountName,
        account: cleanedAccount,
        contract_name: contractName,
        check_num: checkNum,
        business_type: data["报账信息-业务类别"]
    }
}

