function main({data}){
   try {
    // 预处理字符串
    if (typeof data === 'string') {
      // 移除首尾方括号和引号，清理特殊字符
      data = data.replace(/^\s*\[\s*"|"\s*\]\s*$/g, '')  // 移除 ["] 和 ["] 包装
                 .replace(/\\n/g, '')                    // 移除转义换行符
                 .replace(/\n/g, '')                     // 移除实际换行符
                 .replace(/\\r/g, '')                    // 移除转义回车符
                 .replace(/\r/g, '')                     // 移除实际回车符
                 .replace(/\\t/g, '')                    // 移除转义制表符
                 .replace(/\t/g, '')                     // 移除实际制表符
                 .replace(/\\"/g, '"')                   // 处理转义双引号
                 .replace(/\s+/g, ' ')                   // 合并空格
                 .trim();
    }

    // 解析JSON（可能需要多次解析）
    let result = data;
    while (typeof result === 'string') {
      try {
        result = JSON.parse(result);
      } catch {
        break;
      }
    }

    // 处理数组
    if (Array.isArray(result)) {
      result = result[0];
    }

    // 再次确保不是字符串
    while (typeof result === 'string') {
      try {
        result = JSON.parse(result);
      } catch {
        break;
      }
    }

    // 提取信息
    const columns = result?.columns || [];

    // 遍历处理columns中的数据
    const processedColumns = columns.map(column => {
      const supplier_name = column['供应商名称'] || '';
      const supplier_account = column['供应商账号'] || '';

      // 清洗accountName：去掉空格、括号及其他特殊符号，只保留中文、英文、数字
      const cleaned_supplier_name = supplier_name ? supplier_name.replace(/[\s\(\)\[\]{}<>《》""''\-_+=%#@!~`\$\^&\*\|\\\/:;?,.【】（）]+/g, '') : '';

      // 清洗供应商账号：去掉半角和全角减号以及其他特殊字符
      const cleaned_supplier_account = supplier_account 
        ? supplier_account.replace(/[\-\u2013\u2014\u2015\u2212]/g, '')  // 移除各种减号：- – — ― −
            .replace(/[\s$$$$$${}<>《》""''_+=%#@!~`\$\^&\*\|\\:;?,.【】（）]+/g, '') // 移除其他特殊字符字符
            .trim()
        : '';

      return {
        "供应商名称": cleaned_supplier_name,
        "供应商账号": cleaned_supplier_account
      };
    });

    return {
      url: result?.url || '',
      columns: processedColumns
    };

  } catch (error) {
    console.error('数据解析错误:', error);
    return { url: '', columns: [] };
  }
}

