function main({data}) {
  // 清理特殊字符
  data = data.replace(/"{/g, '{')
                 .replace(/}"/g, '}')
                 .replace(/\\n/g, '')
                 .replace(/\n/g, '')                     // 移除实际换行符
                 .replace(/\\r/g, '')                    // 移除转义回车符
                 .replace(/\r/g, '')                     // 移除实际回车符
                 .replace(/\\t/g, '')                    // 移除转义制表符
                 .replace(/\t/g, '')                     // 移除实际制表符
                 .replace(/\\"/g, '"')                   // 处理转义双引号
                 .replace(/\s+/g, ' ')                   // 合并空格
                 .trim();
  const jsonArray = JSON.parse(data);
  const res = [];

  // 遍历外层数组
  for (let i = 0; i < jsonArray.length; i++) {
    try {
      const outerItem = jsonArray[i];
      const { url, columns } = outerItem;

      // 遍历columns数组中的每个对象
      for (let j = 0; j < columns.length; j++) {
        const columnItem = columns[j];

        // 判断供应商名称或供应商账号是否至少有一个不为空
        if (
          (columnItem["供应商名称"] && columnItem["供应商名称"].trim() !== "") ||
          (columnItem["供应商账号"] && columnItem["供应商账号"].trim() !== "")
        ) {
          // 如果供应商名称不为空，则清洗供应商名称
          if (columnItem["供应商名称"] && columnItem["供应商名称"].trim() !== "") {
            // 清洗：去掉空格、括号及其他特殊符号，只保留中文、英文、数字
            columnItem["供应商名称"] = columnItem["供应商名称"].replace(/[\s\(\)\[\]{}<>《》""''\-_+=%#@!~`\$\^&\*\|\\\/:;?,.【】（）]+/g, '');
          }
          // 如果供应商账号不为空，则清洗供应商账号
          if (columnItem["供应商账号"] && columnItem["供应商账号"].trim() !== "") {
            // 清洗供应商账号：去掉半角和全角减号以及其他特殊字符
            columnItem["供应商账号"] = columnItem["供应商账号"].replace(/[\-\u2013\u2014\u2015\u2212]/g, '')  // 移除各种减号：- – — ― −
            .replace(/[\s$$$$$${}<>《》""''_+=%#@!~`\$\^&\*\|\\:;?,.【】（）]+/g, '') // 移除其他特殊字符字符
            .trim();
          }

          // 将外层URL和当前列数据组合成新的对象
          res.push({
            url: url,
            columns: {
              "供应商名称": columnItem["供应商名称"],
              "供应商账号": columnItem["供应商账号"]
            }
          });
        }
      }
    } catch (e) {
      // 忽略无法解析的项，也可以根据需要抛出错误
      console.warn("Invalid JSON string at index", i);
    }
  }

  const groups = [];
  res.forEach(currentItem => {
    const currentName = currentItem.columns["供应商名称"] || "";
    const currentAccount = currentItem.columns["供应商账号"] || "";

    let merged = false;

    // 遍历现有组，寻找可以合并的
    for (let i = 0; i < groups.length; i++) {
      const groupItem = groups[i];
      const groupName = groupItem.columns["供应商名称"] || "";
      const groupAccount = groupItem.columns["供应商账号"] || "";

      // 判断是否可以合并：相同字段必须相等，空值视为匹配
      const canMerge = 
        (!currentName || !groupName || currentName === groupName) &&
        (!currentAccount || !groupAccount || currentAccount === groupAccount);

      if (canMerge) {
        // 计算各自非空字段数量
        const currentNonEmptyCount = 
          (currentName ? 1 : 0) + (currentAccount ? 1 : 0);
        const groupNonEmptyCount = 
          (groupName ? 1 : 0) + (groupAccount ? 1 : 0);

        // 以字段更多的为准进行合并
        if (currentNonEmptyCount > groupNonEmptyCount) {
          // 当前项字段更多，替换组内项
          groups[i] = {
            url: currentItem.url,
            columns: {
              "供应商名称": currentName,
              "供应商账号": currentAccount
            }
          };
        }
        // 如果组内项字段更多或相等，则保持不变

        merged = true;
        break;
      }
    }

    // 如果没有找到可合并的组，创建新组
    if (!merged) {
      groups.push({
        url: currentItem.url,
        columns: {
          "供应商名称": currentName,
          "供应商账号": currentAccount
        }
      });
    }
  });

  return {result: groups}
}

